class Solution {
public:
    int minCharacters(string a, string b) {
        int best = a.size() + b.size();
        for (int c = 0; c < 26; c++) {
            char target = 'a' + c;
            int same = 0;
            for (char ch : a) same += ch != target;
            for (char ch : b) same += ch != target;
            best = min(best, same);
            if (c == 25) break;
            int ab = 0, ba = 0;
            for (char ch : a) { ab += ch > target; ba += ch <= target; }
            for (char ch : b) { ab += ch <= target; ba += ch > target; }
            best = min(best, min(ab, ba));
        }
        return best;
    }
};

