class Solution {
    public int minCharacters(String a, String b) {
        int best = a.length() + b.length();
        for (int c = 0; c < 26; c++) {
            char target = (char) ('a' + c);
            int same = 0;
            for (char ch : a.toCharArray()) if (ch != target) same++;
            for (char ch : b.toCharArray()) if (ch != target) same++;
            best = Math.min(best, same);
            if (c == 25) break;
            int ab = 0, ba = 0;
            for (char ch : a.toCharArray()) { if (ch > target) ab++; if (ch <= target) ba++; }
            for (char ch : b.toCharArray()) { if (ch <= target) ab++; if (ch > target) ba++; }
            best = Math.min(best, Math.min(ab, ba));
        }
        return best;
    }
};

