class Solution:
    def minCharacters(self, a: str, b: str) -> int:
        cnt_a = [0] * 26
        cnt_b = [0] * 26
        for ch in a:
            cnt_a[ord(ch) - 97] += 1
        for ch in b:
            cnt_b[ord(ch) - 97] += 1
        ans = len(a) - max(cnt_a) + len(b) - max(cnt_b)
        for c in range(25):
            above_a = sum(cnt_a[c + 1:])
            below_a = sum(cnt_a[:c + 1])
            above_b = sum(cnt_b[c + 1:])
            below_b = sum(cnt_b[:c + 1])
            ans = min(ans, above_a + below_b, above_b + below_a)
        return ans

