class Solution {
public:
    int minCharacters(string a, string b) {
        vector<int> ca(26, 0), cb(26, 0);
        for (char ch : a) ca[ch - 'a']++;
        for (char ch : b) cb[ch - 'a']++;
        int best = (int)a.size() - *max_element(ca.begin(), ca.end())
                 + (int)b.size() - *max_element(cb.begin(), cb.end());
        for (int c = 0; c < 25; c++) {
            int aboveA = 0, belowA = 0, aboveB = 0, belowB = 0;
            for (int i = c + 1; i < 26; i++) { aboveA += ca[i]; aboveB += cb[i]; }
            for (int i = 0; i <= c; i++) { belowA += ca[i]; belowB += cb[i]; }
            best = min(best, min(aboveA + belowB, aboveB + belowA));
        }
        return best;
    }
};

