class Solution {
    public int minCharacters(String a, String b) {
        int[] ca = new int[26], cb = new int[26];
        for (char ch : a.toCharArray()) ca[ch - 'a']++;
        for (char ch : b.toCharArray()) cb[ch - 'a']++;
        int maxA = 0, maxB = 0;
        for (int i = 0; i < 26; i++) { maxA = Math.max(maxA, ca[i]); maxB = Math.max(maxB, cb[i]); }
        int best = a.length() - maxA + b.length() - maxB;
        for (int c = 0; c < 25; c++) {
            int aboveA = 0, belowA = 0, aboveB = 0, belowB = 0;
            for (int i = c + 1; i < 26; i++) { aboveA += ca[i]; aboveB += cb[i]; }
            for (int i = 0; i <= c; i++) { belowA += ca[i]; belowB += cb[i]; }
            best = Math.min(best, Math.min(aboveA + belowB, aboveB + belowA));
        }
        return best;
    }
};

